def node_lines(r):
    tn = TREES[r["t"]]
    k = "%s.%s." % (tn, r["id"])
    out = ["# %s S%d %s (tier %s)" % (tn, r["s"], r["name"], ["I", "II", "III", "IV", "V", "VI"][r["tier"] - 1])]
    out.append(k + "max=%d" % r["max"])
    if KINDS[r["kind"]] != "FELLER": out.append(k + "per=%s" % repr(float(r["per"])))   # 0.2.4: Tree Feller reads feller.logs
    if KINDS[r["kind"]] in ("VEIN", "DJUMP"): out.append(k + "base=%s" % repr(float(r["base"])))
    out.append(k + "B=%d" % r["B"])
    out.append(k + "tokens=%d" % r["tok"])
    out.append(k + "enabled=true")
    if r["lk"]: out.append(k + r["lk"] + "=" + r["lst"])
    return out
