M(calc, r"""
public static boolean listed(Object o, String key) {
  if (!(o instanceof String) || key == null) return false;
  String s = (String) o;
  int n = s.length();
  int kl = key.length();
  if (kl == 0) return false;
  int a = 0;
  while (a <= n) {
    int c = s.indexOf(',', a);
    if (c < 0) c = n;
    int x = a;
    int y = c;
    while (x < y && s.charAt(x) <= ' ') x++;
    while (y > x && s.charAt(y - 1) <= ' ') y--;
    if (y - x == kl && s.regionMatches(x, key, 0, kl)) return true;
    a = c + 1;
  }
  return false;
}""")
M(calc, r"""
public static boolean reads(String mod, String key) {
  if (mod == null || key == null || mod.length() == 0 || key.length() == 0) return false;
  try {
    java.util.Map b = @PKG@.TreeStore.bridge();
    Object o = b.get("tree:reads:" + mod);
    badFlag("tree:reads:" + mod, o);
    if (listed(o, key)) return true;
    String alias = readerAlias(mod);
    if (alias != null) {
      Object oa = b.get(alias);
      badFlag(alias, oa);
      if (listed(oa, key)) return true;
    }
  } catch (Throwable t) { }
  return false;
}""")
