# 0.3: the tier a tier-<tier> node needs one owned node of: tier - 1, moved down past every tier whose nodes all wait for their reader
# (0 = no requirement). In the 0.2.5 trees nothing is ever coming, so this is always tier - 1 there (0.2.5's rule)
M(calc, r"""
public static int needTier(int t, int tier) {
  int k = tier - 1;
  while (k >= 1 && allComing(t, k)) k--;
  return k;
}""")
M(calc, r"""
public static boolean pathOk(@PKG@.TreeData d, int t, int tier) {
  if (tier <= 1) return true;
  int need = needTier(t, tier);
  if (need < 1) return true;
  for (int k = 0; k < 12; k++) {
    int i = t * 12 + k;
    if (@PKG@.TreeDefs.soon(i)) continue;
    if (@PKG@.TreeDefs.TIER[i] == need && d.lv[i] >= 1) return true;
  }
  return false;
}""")
# 0 locked, 1 unlockable, 2 owned, 3 maxed
M(calc, r"""
public static int state(@PKG@.TreeData d, int i, int lvl, long tokA) {
  if (@PKG@.TreeDefs.soon(i)) return 0;
  int l = d.lv[i];
  if (l >= @PKG@.TreeCfg.MAX[i]) return 3;
  if (l >= 1) return 2;
  if (d.bad || !@PKG@.TreeCfg.EN[i]) return 0;
  if (coming(i)) return 0;   // 0.3: waits for the mod that applies it
  if (lvl < gate(i)) return 0;
  if (!pathOk(d, i / 12, @PKG@.TreeDefs.TIER[i])) return 0;
  if (tokA < (long) @PKG@.TreeCfg.TOK[i]) return 0;
  return 1;
}""")
