# 0.3.1 (Skyy 2026-10-03, "Let waiting nodes be skipped"): the node kinds that can wait for a reader mod - Strength (SkyyGear's
# gear:extras), the Archer crossbow nodes (SkyySkills' key list), Mana Regen (skill:fn:manaregen). Health / Mana nodes, the rune / element
# slots and (by its kind) the ROOT are never skipped.
M(cls, r"""
public static boolean skipKind(int ci, int n) {
  if (ci < 0 || ci >= NC || n < 0 || n >= NN || slotComing(n)) return false;
  int k = CK[ci * NN + n];
  return k == K_S || k == K_X || k == K_R;
}""")
# 0.3.1: the SKIPPED nodes of an owned set - unowned, switched on, of a kind that can wait, and either waiting for its reader right now
# or still holding up an owned node below it (a node bought through it while it waited, so nothing breaks or refunds when the reader
# appears). Computed from the leaves up (a child always comes after its parents in the table), so a chain of skipped nodes (C1 > C2 >
# C3 owned) keeps holding as a whole. A node an admin switched off is never a skip (its chain breaks, as in 0.3).
M(cls, r"""
public static boolean[] skips(boolean[] own, int ci) {
  boolean[] sk = new boolean[NN];
  if (own == null || ci < 0 || ci >= NC) return sk;
  boolean[] hold = new boolean[NN];
  for (int n = NN - 1; n >= 0; n--) {
    boolean h = false;
    for (int c = n + 1; c < NN && !h; c++) {
      if (NPAR1[c] != n && NPAR2[c] != n) continue;
      if ((own[c] && on(ci, c) && !slotComing(c)) || (sk[c] && hold[c])) h = true;
    }
    hold[n] = h;
    if (own[n] || !on(ci, n) || !skipKind(ci, n)) continue;
    sk[n] = h || coming(ci, n);
  }
  return sk;
}""")
# INTEGRITY (spec 5 + 0.3.1): an owned node counts only while its chain is intact - the root, an owned intact parent or a SKIPPED parent
# (0.3.1) leads to it, every Need intact, no Lock owned, switched on, not a coming slot. Iterated to a fixpoint, so a dropped node drops
# what hangs off it. A skipped node is passed (ps), never intact: it is never spent and gives nothing.
M(cls, r"""
public static boolean[] intactOf(boolean[] own, int ci) {
  boolean[] it = new boolean[NN];
  if (own == null || ci < 0 || ci >= NC) return it;
  boolean[] sk = skips(own, ci);
  boolean[] ok = new boolean[NN];
  for (int n = 0; n < NN; n++) ok[n] = own[n] && on(ci, n) && !slotComing(n);
  boolean[] ps = new boolean[NN];
  boolean again = true;
  while (again) {
    again = false;
    for (int n = 0; n < NN; n++) { it[n] = false; ps[n] = false; }
    if (ok[0]) {
      it[0] = true;
      boolean ch = true;
      while (ch) {
        ch = false;
        for (int n = 1; n < NN; n++) {
          if (it[n] || ps[n] || !(ok[n] || sk[n])) continue;
          int p1 = NPAR1[n];
          int p2 = NPAR2[n];
          if ((p1 >= 0 && (it[p1] || ps[p1])) || (p2 >= 0 && (it[p2] || ps[p2]))) {
            if (ok[n]) it[n] = true; else ps[n] = true;
            ch = true;
          }
        }
      }
    }
    for (int n = 0; n < NN; n++) {
      if (!it[n]) continue;
      int nd = NNEED[n];
      int lk = NLOCK[n];
      if ((nd >= 0 && !it[nd]) || (lk >= 0 && own[lk])) { ok[n] = false; again = true; }
    }
  }
  return it;
}""")
M(cls, r"""
public static boolean[] intact(@PKG@.TreeData d, int ci) {
  if (d == null || ci < 0 || ci >= NC || d.bad) return new boolean[NN];
  return intactOf(ownOf(d, ci), ci);
}""")
# 0.3.1: the skipped nodes a player passes right now - a skip whose parent is intact or passed itself (one pass in table order; the
# same set intactOf reaches)
M(cls, r"""
public static boolean[] passed(boolean[] own, boolean[] it, int ci) {
  boolean[] ps = new boolean[NN];
  if (own == null || it == null || ci < 0 || ci >= NC || !it[0]) return ps;
  boolean[] sk = skips(own, ci);
  for (int n = 1; n < NN; n++) {
    if (!sk[n]) continue;
    int p1 = NPAR1[n];
    int p2 = NPAR2[n];
    if ((p1 >= 0 && (it[p1] || ps[p1])) || (p2 >= 0 && (it[p2] || ps[p2]))) ps[n] = true;
  }
  return ps;
}""")
# 0.3.1: the passed nodes a chain really runs through (their bars turn gold): from the leaves up, an intact or used node with no intact
# parent of its own uses its first passed parent (the pick-one pair: a skipped Edge is not "used" when Bulwark is owned)
M(cls, r"""
public static boolean[] used(boolean[] it, boolean[] ps) {
  boolean[] us = new boolean[NN];
  if (it == null || ps == null) return us;
  for (int c = NN - 1; c >= 1; c--) {
    if (!(it[c] || us[c])) continue;
    int p1 = NPAR1[c];
    int p2 = NPAR2[c];
    if ((p1 >= 0 && it[p1]) || (p2 >= 0 && it[p2])) continue;
    if (p1 >= 0 && ps[p1]) us[p1] = true;
    else if (p2 >= 0 && ps[p2]) us[p2] = true;
  }
  return us;
}""")
# 0.3.1: the nodes whose bars may be gold - intact, or a skipped node a chain uses (pieceGold's input on the class page)
M(cls, r"""
public static boolean[] lit(boolean[] own, boolean[] it, int ci) {
  boolean[] r = new boolean[NN];
  if (it == null) return r;
  boolean[] us = used(it, passed(own, it, ci));
  for (int n = 0; n < NN; n++) r[n] = it[n] || us[n];
  return r;
}""")
# 0.3.1: the lane rule counts the owned intact AND the passed nodes of the lane ("as if the path passed through it")
M(cls, r"""
public static int laneHas(boolean[] it, boolean[] ps, int lane) {
  int s = 0;
  for (int n = 0; n < NN; n++) if ((it[n] || (ps != null && ps[n])) && NLANE[n] == lane) s++;
  return s;
}""")
# 0.3.1: the node to name instead of a skipped parent - up the parent line past every skip (a skip has one parent in this map)
M(cls, r"""
public static int gate(boolean[] sk, int p) {
  int g = p;
  int guard = 0;
  while (g >= 0 && sk[g] && guard < NN) { g = NPAR1[g]; guard++; }
  return g < 0 ? p : g;
}""")
