M(page, TR_BUILD_JAVA)
M(page, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  try {
    if (data == null) return;
    java.util.UUID u = this.playerRef.getUuid();
    if (data.indexOf("trback\"") >= 0) {
      if (!@PKG@.TreeCalc.hasSkills()) { this.msg = "SkyySkills is not installed - there is no skills page"; rebuild(); return; }
      @CMGR@.get().handleCommand(this.playerRef, "skills");
      return;
    }
    boolean ctab = this.probe || @PKG@.TreeCfg.CLASS_ON;   // 0.3 part 2: the class tab, its cells, pager, Unlock, Undo, Respec
    if (!ctab && this.tree == @PKG@.TreeDefs.NT) {   // 0.3 fix K: class trees went OFF while this class page was open - show Mining, act on nothing
      this.tree = 0; this.sel = 1; this.msg = "Class trees were switched off - this is the Mining tree now"; this.armT = -1; this.undo.clear();
      LASTTREE.put(u, Integer.valueOf(0));
      rebuild();
      return;
    }
    if (ctab && data.indexOf("trtab" + @PKG@.TreeDefs.NT + "\"") >= 0) {
      this.tree = @PKG@.TreeDefs.NT; this.sel = 1; this.msg = ""; this.armT = -1;
      LASTTREE.put(u, Integer.valueOf(@PKG@.TreeDefs.NT));
      rebuild();
      return;
    }
    if (ctab && this.tree == @PKG@.TreeDefs.NT) {
      int cci = this.probe ? this.pci : @PKG@.TreeClass.classIdx(@PKG@.TreeClass.classOf(u));
      @PKG@.TreeData cd = (this.probe && this.pd != null) ? this.pd : @PKG@.TreeStore.data(u);
      int clv = this.probe ? @PKG@.TreeClassOps.PROBE_LVL : @PKG@.TreeClass.level(u, cci);
      if (data.indexOf("trpgp\"") >= 0) { if (this.cpage > 0) { this.cpage = 0; this.csel = @PKG@.TreeClass.firstOf(0); } this.msg = ""; rebuild(); return; }
      if (data.indexOf("trpgn\"") >= 0) { if (this.cpage < 1) { this.cpage = 1; this.csel = @PKG@.TreeClass.firstOf(1); } this.msg = ""; rebuild(); return; }
      for (int n = 1; n <= @PKG@.TreeClass.NN; n++) {
        if (data.indexOf("trc" + n + "\"") >= 0) { this.csel = n - 1; this.cpage = @PKG@.TreeClass.NPAGE[n - 1]; this.msg = ""; rebuild(); return; }
      }
      if (data.indexOf("trbuy\"") >= 0) { this.msg = @PKG@.TreeClassOps.buy(u, cd, cci, clv, this.csel, this.undo, this.probe); rebuild(); return; }
      if (data.indexOf("trundo\"") >= 0) { this.msg = @PKG@.TreeClassOps.undo(u, cd, cci, this.undo, this.probe); rebuild(); return; }
      if (data.indexOf("trrespec\"") >= 0) {
        long cnow = System.currentTimeMillis();
        long pnow = @PKG@.TreeClassOps.priceOf(cd, cci, clv, this.probe);
        boolean armedNow = this.armT == @PKG@.TreeDefs.NT && cnow - this.armAt <= 10000L;
        if (armedNow && pnow == this.armPrice) {
          this.armT = -1;
          this.msg = @PKG@.TreeClassOps.respec(u, cd, cci, clv, this.probe);
          if (this.msg.startsWith("Respec done")) this.undo.clear();
        } else {   // first click, or (0.3 fix N) the price changed since the first click: arm again with the price that will be charged
          this.armT = @PKG@.TreeDefs.NT;
          this.armAt = cnow;
          this.armPrice = pnow;
          boolean cneg = @PKG@.TreeClassOps.negBalance(cd, cci, clv);
          this.msg = @PKG@.TreeClassOps.armText(cci, clv, cneg, this.probe, pnow) + (armedNow ? " (the price changed since your first click)" : "");
        }
        rebuild();
        return;
      }
    }
    for (int i = 0; i < @PKG@.TreeDefs.NT; i++) {
      if (data.indexOf("trtab" + i + "\"") >= 0) {
        this.tree = i; this.sel = 1; this.msg = ""; this.armT = -1;
        LASTTREE.put(u, Integer.valueOf(i));
        rebuild();
        return;
      }
    }
    for (int s = 1; s <= 12; s++) {
      if (data.indexOf("trnode" + s + "\"") >= 0) { this.sel = s; this.msg = ""; rebuild(); return; }
    }
    int t = this.tree;
    if (t < 0 || t >= @PKG@.TreeDefs.NT) t = 0;
    int sl = this.sel;
    if (sl < 1 || sl > 12) sl = 1;
    if (data.indexOf("trbuy\"") >= 0) { this.msg = @PKG@.TreeOps.buy(this.playerRef, t, sl); rebuild(); return; }
    if (data.indexOf("trtoggle\"") >= 0) { this.msg = @PKG@.TreeOps.toggle(this.playerRef, t, sl); rebuild(); return; }
    if (data.indexOf("trrespec\"") >= 0) {
      long now = System.currentTimeMillis();
      if (this.armT == t && now - this.armAt <= 10000L) {
        this.armT = -1;
        this.msg = @PKG@.TreeOps.respec(this.playerRef, t);
      } else {
        this.armT = t;
        this.armAt = now;
        this.msg = "Click Respec again within 10 s to reset the whole " + @PKG@.TreeDefs.TREES[t] + " tree (everything spent comes back)";
      }
      rebuild();
      return;
    }
  } catch (Throwable e) { @PKG@.TreeCfg.warn("tree page event failed: " + e); }
}""")

