# ================= 0.3 TreeMig: the ONE-TIME Alchemy + Smithing update of an existing trees.properties =================
# setup() only, right AFTER TreeCfg.load (so an older file gets its 0.2-0.2.4 blocks first) and BEFORE CfgPub.start. The SkyyCollections
# 0.2.5 CollBypassMig / SkyyMobs 0.1.1 MobMig machinery (reviewed + live), PROJECT-RULES 4: a marker in a comment line = never again;
# the pure text step mgUpdate appends ONE block after the old bytes (kept byte for byte, the file's own line ending, a missing final
# newline added first; every keyed line only when the file has no such key - a hand-set line is KEPT and named in an INFO line); a
# Properties check (the old keys and values + exactly the appended ones); CfgHist.snapshot + mgSaved (no write unless config-history
# really holds the old bytes); CfgRows.atomicWrite (ISO-8859-1); one config-changes.log line in the kit's table format for the Mining
# rate (old effective rate -> 5) so Server Setup -> Changes -> Undo puts it back. Plain java.* + the kit's classes (a bare JVM runs it
# on scratch copies). Methods after the config kit (CFG.emit made the Cfg* classes above).
mig = pool.makeClass(PKG + ".TreeMig")
for _d in ("public static final String MG_MARK_ID = %s;" % json.dumps(MG_MARK_ID),
           "public static final String MG_WHO = %s;" % json.dumps(MG_WHO),
           'public static final String MINING_KEY = "dust.xpPerDust.Mining";',
           "public static final String MINING_NEW = %s;" % json.dumps(str(DUST_DEF["Mining"])),
           "public static final String[] ADD_KEY = %s;" % jstr([_k for _k, _l in ADD03]),
           "public static final String[] ADD_LINE = %s;" % jstr([_l for _k, _l in ADD03])):
    F(mig, _d)
# the marker in a COMMENT line (logical lines read with the kit's own parser, so a continued value's tail is never taken for a comment)
M(mig, r"""
public static boolean marked(java.util.ArrayList l) {
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) { if (s.indexOf(MG_MARK_ID) >= 0) return true; k++; continue; }
    k = @PKG@.CfgFile.end(l, k) + 1;
  }
  return false;
}""")
# the Dust rate Mining followed before 0.3: the file's dust.xpPerDust as TreeCfg.apply reads it (default 10)
M(mig, r"""
public static long oldRate(java.util.Properties p) {
  return @PKG@.TreeCfg.clampL(@PKG@.TreeCfg.lng(p, "dust.xpPerDust", 10L), 1L, 1000000000L);
}""")
# pure text step (ISO-8859-1 chars in and out). null = the marker is already in a comment line, or the text cannot be read as Properties
# (nothing to do). Else { new text, String[] { key, old, new }* (the change-log rows), String[] kept notes, Integer lines added,
# String[] { appended key, value }* }. Never throws for any text.
M(mig, r"""
public static Object[] mgUpdate(String text) {
  try {
    String[] raw = text.split("\n", -1);
    java.util.ArrayList l = new java.util.ArrayList();
    for (int i = 0; i < raw.length; i++) {
      String s0 = raw[i];
      if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1);
      l.add(s0);
    }
    if (marked(l)) return null;
    java.util.Properties p = new java.util.Properties();
    p.load(new java.io.StringReader(text));
    String eol = text.indexOf("\r\n") >= 0 ? "\r\n" : "\n";
    StringBuilder sb = new StringBuilder(text.length() + 16384);
    sb.append(text);
    if (text.length() > 0 && !text.endsWith("\n")) sb.append(eol);
    if (text.length() > 0) sb.append(eol);
    java.util.ArrayList kept = new java.util.ArrayList();
    java.util.ArrayList keys = new java.util.ArrayList();
    int added = 0;
    // a file that already holds every keyed line (its marker removed by hand) only gets the marker line back (ADD_LINE[0])
    int missing = 0;
    for (int i = 0; i < ADD_LINE.length; i++) if (ADD_KEY[i].length() > 0 && p.getProperty(ADD_KEY[i]) == null) missing++;
    for (int i = 0; i < ADD_LINE.length; i++) {
      String k = ADD_KEY[i];
      if (k.length() > 0 && p.getProperty(k) != null) {
        if (k.startsWith("dust.xpPerDust.")) kept.add(k + "=" + @PKG@.CfgRows.oneLine(p.getProperty(k).trim()) + " kept (an admin's value) - the 0.3 default is " + ADD_LINE[i].substring(k.length() + 1) + " XP per Dust (Server Setup -> Trees -> Dust rate per tree)");
        continue;
      }
      if (missing == 0 && i > 0) continue;
      sb.append(ADD_LINE[i]).append(eol);
      if (k.length() > 0) {
        added++;
        keys.add(k);
        keys.add(ADD_LINE[i].substring(k.length() + 1));
      }
    }
    java.util.ArrayList rows = new java.util.ArrayList();
    if (p.getProperty(MINING_KEY) == null) {
      String old = String.valueOf(oldRate(p));
      if (!old.equals(MINING_NEW)) { rows.add("dust.perTree[Mining]"); rows.add(old); rows.add(MINING_NEW); }
    }
    return new Object[] { sb.toString(), (String[]) rows.toArray(new String[0]), (String[]) kept.toArray(new String[0]), Integer.valueOf(added), (String[]) keys.toArray(new String[0]) };
  } catch (Throwable t) { return null; }
}""")
# the update may only ADD keys: both texts as java.util.Properties - every old key keeps its value, the appended keys hold exactly their
# values and nothing else is there (guards the parser corner cases: a continued last line, an odd separator)
M(mig, r"""
public static boolean sameAfter(byte[] old, byte[] nb, String[] keys) {
  try {
    java.util.Properties a = new java.util.Properties();
    java.util.Properties b = new java.util.Properties();
    a.load(new java.io.ByteArrayInputStream(old));
    b.load(new java.io.ByteArrayInputStream(nb));
    if (b.size() != a.size() + keys.length / 2) return false;
    java.util.Iterator it = a.stringPropertyNames().iterator();
    while (it.hasNext()) {
      String k = (String) it.next();
      if (!a.getProperty(k).equals(b.getProperty(k))) return false;
    }
    for (int i = 0; i + 1 < keys.length; i += 2) {
      if (a.getProperty(keys[i]) != null || !keys[i + 1].equals(b.getProperty(keys[i]))) return false;
    }
    return true;
  } catch (Throwable t) { return false; }
}""")
M(mig, r"""
public static int fileIdx() {
  for (int k = 0; k < @PKG@.CfgRows.FILES.length; k++) if (@PKG@.CfgRows.FILES[k].endsWith("/trees.properties")) return k;
  return -1;
}""")
# the config kit's own files for the update, before CfgPub.start (which sets the same values again): history + change log live in the
# folder of trees.properties (the kit's HOME, Skyy_SkyyTrees)
M(mig, r"""
public static void mgKit(java.nio.file.Path home) {
  @PKG@.CfgRows.HOME = home;
  if (@PKG@.CfgRows.LOG == null) @PKG@.CfgRows.LOG = @PKG@.TreeCfg.LOG;
  @PKG@.CfgHist.init();
  @PKG@.CfgLog.init();
}""")
# CfgHist.snapshot swallows its own errors, so after it the update checks that config-history really holds a copy with exactly these
# bytes (the new copy, or the newest one when snapshot skipped an equal file) - the copies themselves, not index.log
M(mig, r"""
public static boolean mgSaved(int f, byte[] old) {
  String[] have = @PKG@.CfgHist.list(f);
  for (int i = have.length - 1; i >= 0; i--) {
    try {
      if (java.util.Arrays.equals(java.nio.file.Files.readAllBytes(@PKG@.CfgHist.bak(f, have[i])), old)) return true;
    } catch (Throwable x) { }
  }
  return false;
}""")
# one config-changes.log line in the kit's format (CfgLog.add without its per-line INFO); a table entry is keyed tableKey[entry], so
# Server Setup -> Changes undoes it with a tset of the entry back to the old value
M(mig, r"""
public static String mgLog(String k, String o, String n) {
  return @PKG@.CfgLog.now() + "\t" + MG_WHO + "\t-\tupdate\t" + @PKG@.CfgRows.oneLine(k) + "\t" + o + "\t" + n + "\tok";
}""")
# setup(): the file before this update becomes a History version (KEEP 10, verified by mgSaved before the write), the new text is
# written with the kit's atomicWrite (ISO-8859-1 bytes), one change-log line for the Mining rate, INFO lines. Returns them joined by \n
# ("" = nothing done: no file - TreeCfg.load writes the 0.3 default with the marker -, marker already there, or a failure - WARN,
# file untouched, retried at the next start; the code default already gives Mining 5 meanwhile)
M(mig, r"""
public static synchronized String run(java.nio.file.Path base) {
  if (base == null) return "";
  java.nio.file.Path f = base.resolve("trees.properties");
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = mgUpdate(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    String[] keys = (String[]) r[4];
    if (!sameAfter(old, data, keys)) {
      @PKG@.TreeCfg.warn("trees.properties NOT updated for SkyyTrees 0.3: the update would change more than the added lines (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = fileIdx();
    if (fi < 0) return "";
    mgKit(f.toAbsolutePath().getParent());
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), MG_WHO, "before the 0.3 Alchemy + Smithing trees update");
    if (!mgSaved(fi, old)) {
      @PKG@.TreeCfg.warn("trees.properties NOT updated for SkyyTrees 0.3: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (the file is used as it is; the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[1];
    for (int i = 0; i + 2 < rows.length; i += 3) @PKG@.CfgLog.enqueue(mgLog(rows[i], rows[i + 1], rows[i + 2]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String[] kept = (String[]) r[2];
    int added = ((Integer) r[3]).intValue();
    String rate = rows.length > 0 ? "; Mining earns 1 Dust per " + rows[2] + " XP now (was " + rows[1] + " - Skyy 2026-10-02: Mining Dust doubled; Server Setup -> Trees -> Changes can undo it)" : "";
    String msg = "trees.properties updated for SkyyTrees 0.3: " + added + " line(s) added - the Alchemy, Smithing and class trees and the Dust rates" + rate + " (the old file is in config-history)";
    @PKG@.TreeCfg.info(msg);
    StringBuilder all = new StringBuilder(msg);
    for (int i = 0; i < kept.length; i++) { @PKG@.TreeCfg.info(kept[i]); all.append('\n').append(kept[i]); }
    return all.toString();
  } catch (Throwable t) {
    @PKG@.TreeCfg.warn("could not update trees.properties for SkyyTrees 0.3 (the file is used as it is): " + t);
    return "";
  }
}""")

